ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	query: p('db.searchWithDRXIdList'),
	inputParameters: {
		"drx_ids": (vars.routing.prescriptionIds default []) joinBy ",",
		"entity": p('prescription')
	}
}

%dw 2.0
import * from dw::core::Strings
output application/json
var rows = vars.dbSearchResponse default []
var code = rows[0].provider_code default ""
// provider_external_id is the partner's own id; external_id is only the row key
fun extOf(row) = if (isEmpty(row.provider_external_id)) row.external_id else row.provider_external_id
fun refOf(row) = do {
	var ext = extOf(row)
	---
	if (ext is String) (if (ext startsWith (code ++ ":")) substringAfter(ext, ":") else ext) else ext
}
var mine = rows filter ((r) -> r.provider_code == code)
---
{
	code: code,
	ref: if (isEmpty(mine)) null else refOf(mine[0]),
	source: if (isEmpty(code)) null else "db",
	prescriptionId: vars.routing.prescriptionId,
	// the partner's order id for each of its prescriptions on this label
	refsByRx: {( mine map ((r) -> { ((r.drx_id default "") as String): refOf(r) }) )}
}

%dw 2.0
output application/json
var base = if (isEmpty(vars.provider)) null else vars.connectionDetails[vars.provider]
---
if (base == null) null else (vars.provider match {
	case "PMD" -> base ++ {
		"queryParams": {
			"event": "shipping_label"
		}
	}
	case "WLM" -> base ++ {
		"uriParams": {
			"event": "shipped"
		}
	}
	else -> base
})

%dw 2.0
output application/java
var halted = (error.errorType.identifier default "") == "HALT_FLOW"
var partnerMessage = vars.error.errorMessage
var partnerText = if (partnerMessage is String) partnerMessage
	else if ((partnerMessage is Object) or (partnerMessage is Array)) write(partnerMessage, "application/json", {indent: false})
	else ""
var detail = if (halted) ((vars.error.errorType default "") ++ " " ++ partnerText)
	else ((error.errorType.namespace default "") ++ ":" ++ (error.errorType.identifier default ""))
---
{
	"status": if (halted) "rejected" else "failed",
	"httpStatus": null,
	"error": if (sizeOf(detail) > 300) detail[0 to 299] else detail
}

%dw 2.0
output application/java
fun epochOf(s) = if ((s is String) and (sizeOf(s) >= 19)) (((s[0 to 18] ++ "Z") as DateTime) as Number {unit: "seconds"}) else 0
var settleS = (now() as Number {unit: "seconds"}) - ((vars.sweep.settleMinutes as Number) * 60)
// DEV only: test labels from config, routed through the real DRX lookups and the real partner call
var fixtures = if (vars.sweep.fixture) read(p('labelSweep.fixtureLabels'), "application/json") else []
var all = (vars.realLabels ++ fixtures) distinctBy ($.id)
var eligible = (all filter ((l) -> ((l.id as Number) > (vars.baseline as Number))
	and !(l.voided default false)
	and !(isEmpty(l.tracking_number))
	and (epochOf(l.created_at) <= settleS))) orderBy ($.id as Number)
var capped = if (sizeOf(eligible) > vars.sweep.maxLabels) eligible[0 to (vars.sweep.maxLabels - 1)] else eligible
var fixtureIds = fixtures map ($.id as Number)
var olderReal = (vars.realLabels filter (epochOf($.created_at) <= settleS)) map ($.id as Number)
var cappedReal = (capped map ($.id as Number)) filter ((i) -> !(fixtureIds contains i))
---
{
	read: sizeOf(vars.realLabels),
	fixtures: sizeOf(fixtures),
	eligible: sizeOf(eligible),
	candidates: capped,
	// next run pages back to this id (minus a margin); when capped, only as far as this run got
	highWater: if (sizeOf(eligible) > vars.sweep.maxLabels) (max(cappedReal) default vars.highWater) else (max(olderReal) default vars.highWater)
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
var l = vars.label
---
{
	"shipment": {
		"id": l.id,
		"tracking_number": l.tracking_number,
		"carrier_code": l.carrier_code,
		"service_code": l.service_code
	},
	"fills": ((vars.labelFills default []) filter (($ != null) and ($.fill != null))) map ((pf) -> {
		"id": pf.fill.id,
		"prescription_id": pf.prescription.id,
		"external_id": null,
		"status": pf.fill.status,
		"prescription": {
			"id": pf.prescription.id,
			"surescripts_erx_id": pf.prescription.surescripts_erx_id,
			"surescripts_erx_order_number": pf.prescription.surescripts_erx_order_number
		}
	})
}

db:insert.db:input-parameters:
#[%dw 2.0
output application/java
var masked = attributes.headers mapObject ((v, k) -> { (k): if ((k as String) matches /(?i).*(secret|authorization|token|password|key|cookie).*/) "<masked>" else v })
---
{
	"path": attributes.requestPath ++ (if (isEmpty(attributes.queryString)) "" else ("?" ++ attributes.queryString)),
	"headers": write(masked, "application/json", {indent: false}),
	"body": if (payload == null) "" else write(payload, "application/json", {indent: false})
}]
